// t01: the analytical petty cash book and the imprest system (imprest, reimbursement at the period end, balancing,
// posting of the column totals). Imagined firms; every book is generated by pettyCash() and asserted.
import { mcq, ar, tf, fb, short, long } from './lib.mjs';
import { same, check, sum, inr, rs, mdTable, pettyCash, V } from './books.mjs';
import { QQ, numQ } from './qq.mjs';

// ================================================================ multiple choice
QQ('m_pc_imprest_def', mcq({
  t: 1, d: 1, c: 'recall',
  stem: 'Sundar Rice Mills, an imagined firm, gives its petty cashier the same fixed sum at the start of every week and, at the week end, pays him exactly the amount he has spent. This method of keeping petty cash is called the',
  opts: ['imprest system', 'cash discount system', 'columnar cash system', 'contra system'],
  sol: 'A fixed float that is topped up by the amount spent is the imprest system. A cash discount is an allowance for early payment, a contra entry moves funds between cash and bank, and no system named columnar cash exists.',
}));
QQ('m_pc_columns', mcq({
  t: 1, d: 2, c: 'understanding',
  stem: 'What does an analytical petty cash book kept by Palani Dairy Products, an imagined firm, show that a petty cash book with a single amount column does not?',
  opts: ['The payments sorted into columns by the head of expense, with a total for each head', 'The payments sorted by customer and by supplier', 'The balance of the bank account after each payment', 'The profit made on each voucher'],
  sol: 'The analysis columns collect like expenses together, so that a column total can be posted to its expense account. Customers, the bank balance and profit are outside a petty cash book.',
}));
const PR = { imprest: 3000, vouchers: [V('1', '1', 'a', { Postage: 380 }), V('2', '2', 'b', { Stationery: 745 }), V('3', '3', 'c', { Conveyance: 615 }), V('4', '4', 'd', { Sundries: 500 })] };
const PRB = pettyCash({ ...PR, heads: ['Postage', 'Stationery', 'Conveyance', 'Sundries'] });
same(PRB.reimburse, 2240, 'm_pc_reimburse');
same(PRB.closing, 760, 'm_pc_reimburse balance');
QQ('m_pc_reimburse', mcq({
  t: 1, d: 3, c: 'application',
  stem: 'The imprest of Sundar Rice Mills is ₹3,000. In a week its petty cashier paid ₹380 on postage, ₹745 on stationery, ₹615 on conveyance and ₹500 on sundries. At the week end the head cashier must reimburse',
  opts: [rs(PRB.reimburse), rs(PRB.closing), rs(3000), rs(PRB.reimburse + 3000)],
  sol: `Payments = ${inr(380)} + ${inr(745)} + ${inr(615)} + ${inr(500)} = ${inr(PRB.reimburse)}, and the reimbursement equals the payments. ${rs(PRB.closing)} is only the balance still in the petty cashier's hands, ${rs(3000)} is the imprest itself, and ${rs(PRB.reimburse + 3000)} wrongly adds the imprest to the payments.`,
}));
QQ('m_pc_posting', mcq({
  t: 1, d: 2, c: 'understanding',
  stem: 'At the end of the month, the Stationery column total of the analytical petty cash book of Warangal Cold Stores, an imagined firm, is posted to the ledger by',
  opts: ['debiting Stationery A/c', 'crediting Stationery A/c', 'debiting Petty Cash A/c with the same amount', 'crediting Purchases A/c'],
  sol: 'Stationery is an expense, so its column total is posted to the debit of the Stationery account. Crediting it would reduce the expense, the cash credit is made once for the whole reimbursement, and Purchases has no part in a petty expense.',
}));
QQ('m_chk_imprest', mcq({
  t: 1, d: 2, c: 'understanding',
  stem: 'The petty cashier of Vidisha Plywood, an imagined firm, starts a month with ₹5,000, which is the imprest. After spending ₹3,640 during the month, the amount left with him is',
  opts: [rs(5000 - 3640), rs(3640), rs(5000), rs(5000 + 3640)],
  sol: `Balance in hand = ${inr(5000)} − ${inr(3640)} = ${rs(1360)}. The ${rs(3640)} is the amount spent and to be reimbursed, ${rs(5000)} is the imprest before any spending, and the sum ${rs(8640)} cannot be in hand.`,
}));
QQ('m_pc_compound', mcq({
  t: 1, d: 3, c: 'analysis',
  stem: 'A petty voucher of Dhenkanal Papers, an imagined firm, is for ₹180: a courier charge of ₹60 and ₹120 for the packing tape. How should it be entered in the analytical petty cash book that has Postage, Stationery and Sundries columns?',
  opts: ['₹180 in the Total column, ₹60 under Postage and ₹120 under Sundries', '₹180 in the Total column and ₹180 under Sundries only', '₹60 in the Total column and ₹120 under Sundries', '₹180 in the Total column and nothing in any analysis column'],
  sol: 'The total column carries the whole voucher and the analysis columns split it by head, so the column totals later equal the total of the payments. Putting all of it under Sundries misstates the postage, entering only ₹60 loses part of the payment, and leaving the analysis blank means no expense account is debited.',
}));

// ================================================================ assertion-reason, true-false, fill-blank
QQ('ar_imprest', ar({
  t: 1, d: 3, c: 'analysis', verdict: 'both-true-explains',
  a: 'Under the imprest system the amount the head cashier reimburses at the end of a period equals the total payments made by the petty cashier in that period.',
  r: 'The reimbursement of exactly what was spent brings the petty cashier\'s float back to the fixed imprest.',
  sol: 'Both are true, and the reason says why the reimbursement is the same as the payments: the float must be restored to the fixed sum.',
}));
QQ('tf_pc_same_sum', tf({
  t: 1, d: 2, c: 'understanding', ans: false,
  stem: 'Under the imprest system, Dhanbad Pipes, an imagined firm, gives its petty cashier the same amount of cash at the end of every week, whatever he has spent.',
  sol: 'The head cashier gives the amount actually spent, which differs from week to week. It is the float that is fixed, not the refill.',
}));
QQ('fb_pc_imprest', fb({
  t: 1, d: 1, c: 'recall',
  stem: 'Narmada Tiles, an imagined firm, gives its petty cashier a ______ sum at the start of each month and, at the month end, repays him exactly the amount ______ so that the sum is restored.',
  acc: [['fixed', 'fixed amount', 'definite'], ['spent', 'paid out', 'paid', 'expended']],
  sol: 'The float is fixed and the refill is the amount spent.',
}));

// ================================================================ numerical
const NC = pettyCash({ imprest: 4500, heads: ['Postage', 'Stationery', 'Fares'], vouchers: [V('1', '1', 'a', { Postage: 620 }), V('2', '2', 'b', { Stationery: 1085 }), V('3', '3', 'c', { Fares: 745 }), V('4', '4', 'd', { Fares: 390 })] });
same(NC.closing, 1660, 'n_pc_closing');
QQ('n_pc_closing', numQ({
  t: 1, d: 2, c: 'application', value: NC.closing,
  stem: 'Jhansi Paints, an imagined firm, keeps an imprest of ₹4,500. During a week its petty cashier paid ₹620 for postage, ₹1,085 for stationery and ₹745 and ₹390 for fares. The balance he carries down at the end of the week is (in ₹)',
  sol: `Payments = ${inr(620)} + ${inr(1085)} + ${inr(745)} + ${inr(390)} = ${inr(NC.spent)}; balance c/d = ${inr(4500)} − ${inr(NC.spent)} = ${rs(NC.closing)}.`,
}));
const NR = pettyCash({ imprest: 3500, open: 420, heads: ['Postage'], vouchers: [V('1', '1', 'a', { Postage: 100 })] });
same(NR.received, 3080, 'n_pc_received');
QQ('n_pc_received', numQ({
  t: 1, d: 2, c: 'application', value: NR.received,
  stem: 'The imprest of Kollam Cashew Traders, an imagined firm, is ₹3,500, and at the start of the month ₹420 is left with the petty cashier from the last month. The cash the head cashier gives him at the start of the month is (in ₹)',
  sol: `Cash received = imprest − balance in hand = ${inr(3500)} − ${inr(420)} = ${rs(NR.received)}.`,
}));

// ================================================================ short answer, 2 marks
QQ('s2_pc_imprest_why', short({
  t: 1, d: 2, c: 'understanding', marks: 2,
  stem: 'State two features of the imprest system of petty cash, as followed by an imagined trading firm.',
  model: '1. A fixed sum, the imprest, is given to the petty cashier at the start of a period.\n\n2. At the end of the period the head cashier reimburses exactly the amount spent, so the petty cashier begins the next period with the full imprest again. (Other correct features: the head cashier can control and check the expenses easily; the petty cashier cannot spend beyond the imprest without asking for more.)',
  sol: 'One mark for each feature.',
  scheme: [['A fixed amount (imprest) is given to the petty cashier', 1], ['Reimbursement equal to the amount spent restores the imprest', 1]],
}));
QQ('s2_pc_analytical', short({
  t: 1, d: 2, c: 'understanding', marks: 2,
  stem: 'Why does an imagined wholesaler keep its petty cash book in the analytical (columnar) form? Give two reasons.',
  model: '1. Each payment is recorded once in the Total column and again under its head, so the column totals show at a glance how much was spent on each kind of expense.\n\n2. The total of each column can be posted straight to its expense account in the ledger, which saves posting every small voucher and reduces the chance of error.',
  sol: 'One mark for each reason.',
  scheme: [['Expenses grouped head-wise, with totals available', 1], ['Column totals posted in one entry to the expense accounts', 1]],
}));

// ================================================================ short answer, 3 marks
const P3 = pettyCash({
  imprest: 2500,
  open: 600,
  heads: ['Postage', 'Stationery', 'Travelling', 'Sundries'],
  startDate: '1 Oct',
  closeDate: '31 Oct',
  nextDate: '1 Nov',
  vouchers: [V('4 Oct', '1', 'Postage', { Postage: 340 }), V('12 Oct', '2', 'Stationery', { Stationery: 810 }), V('20 Oct', '3', 'Travelling', { Travelling: 460 }), V('28 Oct', '4', 'Sundries', { Sundries: 290 })],
});
same(P3.spent, 1900, 's3_pc_posting spent');
same(P3.reimburse, 1900, 's3_pc_posting reimbursement');
QQ('s3_pc_posting', short({
  t: 1, d: 3, c: 'application', marks: 3,
  stem: 'The analytical petty cash book of Akola Hosiery, an imagined firm, for October shows column totals of Postage ₹340, Stationery ₹810, Travelling ₹460 and Sundries ₹290. The imprest is ₹2,500 and ₹600 was in hand at the start of the month. (a) Find the amount reimbursed by the head cashier. (b) Show how the column totals are posted to the ledger and how the reimbursement is entered by the head cashier.',
  model: `**(a)** Total payments = ${inr(340)} + ${inr(810)} + ${inr(460)} + ${inr(290)} = ${rs(P3.spent)}, so the amount reimbursed is **${rs(P3.reimburse)}**, and ${rs(P3.closing)} (${inr(2500)} − ${inr(P3.spent)}) is carried down.\n\n**(b)**\n\n${P3.postMd}\n\nIn the ledger the four expense accounts are debited with the column totals; in the cash book the reimbursement of ${rs(P3.reimburse)} is entered on the payment side.`,
  sol: 'Total of the columns is the reimbursement; each head account is debited and cash is credited once.',
  scheme: [['Total payments and reimbursement of ₹1,900 found', 1], ['Postage, Stationery, Travelling and Sundries accounts debited with the column totals', 1], ['Cash credited with the reimbursement of ₹1,900, equal to the debits', 1]],
}));
const P3b = pettyCash({
  imprest: 3000,
  open: 340,
  heads: ['Postage', 'Printing', 'Conveyance'],
  vouchers: [V('3 Jun', '1', 'Stamps', { Postage: 260 }), V('9 Jun', '2', 'Bill books', { Printing: 880 }), V('15 Jun', '3', 'Fare', { Conveyance: 465 }), V('22 Jun', '4', 'Pamphlets and postage', { Printing: 420, Postage: 75 })],
  startDate: '1 Jun', closeDate: '30 Jun', nextDate: '1 Jul',
});
same(P3b.spent, 2100, 's3_pc_period spent');
same(P3b.closing, 900, 's3_pc_period closing');
QQ('s3_pc_period', short({
  t: 1, d: 3, c: 'application', marks: 3,
  stem: 'Gudur Prints, an imagined firm, has an imprest of ₹3,000 and ₹340 in the petty cashier\'s hands on 1 June. In June he paid for stamps ₹260, bill books ₹880, a fare ₹465 and, on 22 June, pamphlets ₹420 together with postage ₹75 on one voucher. Find (a) the cash received from the head cashier on 1 June, (b) the total payments and the balance carried down on 30 June, and (c) the amount reimbursed on 1 July and the sum with the petty cashier after that.',
  model: `**(a)** Cash received = ${inr(3000)} − ${inr(340)} = **${rs(P3b.received)}**.\n\n**(b)** Total payments = ${inr(260)} + ${inr(880)} + ${inr(465)} + ${inr(420 + 75)} = **${rs(P3b.spent)}**; balance c/d = ${inr(3000)} − ${inr(P3b.spent)} = **${rs(P3b.closing)}**.\n\n**(c)** Reimbursement on 1 July = **${rs(P3b.reimburse)}**, so the petty cashier holds ${inr(P3b.closing)} + ${inr(P3b.reimburse)} = **${rs(3000)}**, the imprest.`,
  sol: 'Find the refill at the start, the payments and balance at the end, and then the reimbursement.',
  scheme: [['Cash received at the start ₹2,660', 1], ['Total payments ₹2,100 and balance c/d ₹900', 1], ['Reimbursement ₹2,100 restoring the imprest of ₹3,000', 1]],
}));

// ================================================================ long answer, 5 marks
const L1 = pettyCash({
  imprest: 3000,
  open: 200,
  heads: ['Postage', 'Stationery', 'Conveyance', 'Refreshments', 'Sundries'],
  startDate: '1 Sep',
  closeDate: '30 Sep',
  nextDate: '1 Oct',
  vouchers: [
    V('3 Sep', '1', 'Stamps', { Postage: 150 }),
    V('7 Sep', '2', 'Tea for visitors', { Refreshments: 220 }),
    V('11 Sep', '3', 'Typing paper and files', { Stationery: 640 }),
    V('15 Sep', '4', 'Auto fares', { Conveyance: 380 }),
    V('19 Sep', '5', 'Speed post and cleaning cloth', { Postage: 95, Sundries: 60 }),
    V('24 Sep', '6', 'Tea for the dealers\' meeting', { Refreshments: 310 }),
    V('27 Sep', '7', 'Bus fare and porter', { Conveyance: 170, Sundries: 80 }),
  ],
});
same(L1.spent, 2105, 'l5_pc_book spent');
same(L1.closing, 895, 'l5_pc_book closing');
QQ('l5_pc_book', long({
  t: 1, d: 3, c: 'application', marks: 5,
  stem: 'Prepare the analytical petty cash book of Udaipur Linen Works, an imagined firm, for September 2028 on the imprest system, with columns for Postage, Stationery, Conveyance, Refreshments and Sundries, from these facts. The imprest is ₹3,000 and ₹200 was in the petty cashier\'s hands on 1 September. Payments (voucher number in brackets): 3 Sep stamps ₹150 (1); 7 Sep tea for visitors ₹220 (2); 11 Sep typing paper and files ₹640 (3); 15 Sep auto fares ₹380 (4); 19 Sep speed post ₹95 and a cleaning cloth ₹60 on one voucher (5); 24 Sep tea for the dealers\' meeting ₹310 (6); 27 Sep bus fare ₹170 and porter ₹80 on one voucher (7). Balance the book and show the reimbursement on 1 October.',
  model: `${L1.md}\n\nTotal payments = ${rs(L1.spent)}; balance c/d = ${inr(3000)} − ${inr(L1.spent)} = ${rs(L1.closing)}; reimbursement on 1 October = ${rs(L1.reimburse)}, which restores the imprest of ${rs(3000)}.`,
  sol: 'Receipts first, then each voucher in the total and in its heads, then the totals, the balance and the reimbursement.',
  scheme: [['Opening balance ₹200 and cash received ₹2,800 on the receipts side', 1], ['Seven vouchers entered in date order with the total column', 1], ['Compound vouchers split correctly under their heads', 1], ['Column totals ₹2,105 agreeing with the total payments, and balance c/d ₹895', 1], ['Reimbursement ₹2,105 and balance b/d on 1 October, totals ₹3,000', 1]],
}));
const W1 = pettyCash({ imprest: 2000, heads: ['Postage', 'Stationery', 'Fares', 'Sundries'], startDate: '3 Apr', closeDate: '8 Apr', nextDate: '10 Apr', vouchers: [V('3 Apr', '1', 'Stamps', { Postage: 120 }), V('4 Apr', '2', 'Pens and a stapler', { Stationery: 340 }), V('6 Apr', '3', 'Auto fare', { Fares: 90 }), V('8 Apr', '4', 'Kitchen supplies', { Sundries: 215 })] });
const W2 = pettyCash({ imprest: 2000, open: W1.closing, heads: ['Postage', 'Stationery', 'Fares', 'Sundries'], startDate: '10 Apr', closeDate: '15 Apr', nextDate: '17 Apr', vouchers: [V('10 Apr', '5', 'Courier', { Postage: 185 }), V('11 Apr', '6', 'Ledger and ink', { Stationery: 415 }), V('13 Apr', '7', 'Rickshaw fare', { Fares: 75 }), V('15 Apr', '8', 'Repair of a stool', { Sundries: 150 })] });
same(W1.spent, 765, 'l5_pc_two spent 1');
same(W1.closing, 1235, 'l5_pc_two closing 1');
same(W2.received, W1.reimburse, 'second week refill equals the first week reimbursement');
same(W2.spent, 825, 'l5_pc_two spent 2');
same(W2.closing, 1175, 'l5_pc_two closing 2');
QQ('l5_pc_two_weeks', long({
  t: 1, d: 4, c: 'application', marks: 5,
  stem: 'Ludhiana Leather House, an imagined firm, started its petty cash on 3 April 2028 with an imprest of ₹2,000. Week 1 (3 to 8 April): stamps ₹120 (voucher 1), pens and a stapler ₹340 (2), an auto fare ₹90 (3), kitchen supplies ₹215 (4). The head cashier reimbursed the payments on 10 April. Week 2 (10 to 15 April): a courier ₹185 (5), a ledger and ink ₹415 (6), a rickshaw fare ₹75 (7), repair of a stool ₹150 (8). (a) Find the balance carried down and the amount reimbursed for week 1 [2]. (b) Prepare the analytical petty cash book for week 2 with columns for Postage, Stationery, Fares and Sundries, showing the balance carried down [3].',
  model: `**(a)** Week 1: payments = ${inr(120)} + ${inr(340)} + ${inr(90)} + ${inr(215)} = ${rs(W1.spent)}; balance c/d = ${inr(2000)} − ${inr(W1.spent)} = **${rs(W1.closing)}**; reimbursed on 10 April = **${rs(W1.reimburse)}**.\n\n**(b)** Week 2 opens with ${rs(W1.closing)} in hand plus the ${rs(W2.received)} just reimbursed, which is the imprest of ${rs(2000)}.\n\n${W2.md}\n\nTotal payments = ${rs(W2.spent)}; balance c/d = **${rs(W2.closing)}**.`,
  sol: 'Reimbursement of week 1, then week 2 begins with the restored imprest.',
  scheme: [['Week 1 payments ₹765 and balance c/d ₹1,235', 1], ['Reimbursement ₹765 on 10 April', 1], ['Week 2 receipts ₹1,235 and ₹765 and the four vouchers in the total column and heads', 1], ['Column totals ₹825 agreeing with the total payments', 1], ['Balance c/d ₹1,175 with equal totals of ₹2,000', 1]],
}));
